<!--
  CORE-6161: the validation assistant in its own browser window (board + chat).
  The validation screen opens this and hands over the blocker snapshot, because a
  separate window shares no Pinia state and cannot build the form-builder model.
-->
<template>
  <div class="validation-assistant-window">
    <ValidationAssistantPanel
      v-if="ready"
      ref="panel"
      :doc-id="docId"
      :blockers="snapshot"
      :has-ai-table="hasAiTable"
      :orphaned="orphaned"
      :screen="screen"
      window-mode
      @close="closeWindow"
      @open-validation="openValidationInOpener"
      @conversation-change="syncConversationToOpener"
    />
  </div>
</template>

<script lang="ts">
import { defineComponent } from 'vue';
import ValidationAssistantPanel from 'src/components/ValidationAssistant/ValidationAssistantPanel.vue';
import {
  VALIDATION_ASSISTANT_CHANNEL,
  type ValidationAssistantBusMessage,
} from 'src/utils/validationAssistantWindowBus';
import type { ValidationBlockers } from 'src/utils/validationBlockers';
import type { AssistantScreen } from 'src/services/validationAssistant/validationAssistantService';

type PanelConversationApi = {
  exportConversation?: () => unknown;
  importConversation?: (state: unknown) => void;
};

const SIZE_KEY = 'docbits:validation-assistant:size';
const DEFAULT_WIDTH = 820;
const DEFAULT_HEIGHT = 960;

function readSavedSize(): { width: number; height: number } | null {
  try {
    const raw = localStorage.getItem(SIZE_KEY);
    if (!raw) return null;
    const parsed = JSON.parse(raw);
    if (typeof parsed?.width === 'number' && typeof parsed?.height === 'number') {
      return { width: parsed.width, height: parsed.height };
    }
  } catch {
    // ignore malformed storage
  }
  return null;
}

export default defineComponent({
  name: 'ValidationAssistantWindow',

  components: { ValidationAssistantPanel },

  data() {
    return {
      /** Pushed by the opener; stays null when the window was opened standalone. */
      snapshot: null as ValidationBlockers | null,
      hasAiTable: false,
      ready: false,
      orphaned: false,
      channel: null as BroadcastChannel | null,
    };
  },

  computed: {
    screen(): AssistantScreen {
      const screen = String(this.$route.query.screen || '');
      return screen === 'po_match' || screen === 'accounting' ? screen : 'validation';
    },
    docId(): string {
      return String(this.$route.params.id || '');
    },
  },

  mounted() {
    this.applySavedSize();
    this.pullSnapshotFromOpener();
    this.ready = true;
    this.$nextTick(() => this.pullConversationFromOpener());
    // CORE-6161 popout: no opener (standalone open, opener navigated/reloaded)
    // means the window has nothing to work from — show the empty state.
    this.orphaned = !this.hasOpener();
    window.addEventListener('focus', this.onWindowFocus);
    window.addEventListener('beforeunload', this.notifyParentOnClose);
    // this reference is being used from the opener window
    (<any>window).ValidationAssistantWindow = this;
    this.channel = this.openChannel();
  },

  beforeUnmount() {
    window.removeEventListener('focus', this.onWindowFocus);
    window.removeEventListener('beforeunload', this.notifyParentOnClose);
    this.channel?.close();
    this.channel = null;
  },

  methods: {
    // CORE-6161: the validation screen, or a PO matching / accounting screen.
    openerHost(): any {
      try {
        const opener = (<any>window).opener;
        return opener?.ValidationAssistantHostView || opener?.FieldValidationView || null;
      } catch {
        return null;
      }
    },
    openValidationInOpener(field: string) {
      const host = this.openerHost();
      if (!host?.openValidationAtField) return;
      this.handOverChat();
      host.openValidationAtField(field);
      window.close();
    },
    hasOpener(): boolean {
      try {
        return !!window.opener && !window.opener.closed;
      } catch {
        return false;
      }
    },
    openChannel(): BroadcastChannel | null {
      if (typeof BroadcastChannel === 'undefined') return null;
      const channel = new BroadcastChannel(VALIDATION_ASSISTANT_CHANNEL);
      channel.onmessage = (event: MessageEvent<ValidationAssistantBusMessage>) => {
        const message = event.data;
        if (message?.type === 'blockers') {
          // The opener switched documents — follow it so the window always
          // shows the blockers of the document the user is actually on.
          if (message.docId && message.docId !== this.docId) {
            this.$router.replace({
              path: '/show_validation_assistant/' + encodeURIComponent(message.docId),
            });
          }
          this.snapshot = (message.snapshot as ValidationBlockers) || null;
          if (this.snapshot) this.orphaned = false;
        }
      };
      return channel;
    },
    onWindowFocus() {
      // The opener may have navigated or reloaded since open; re-pull the
      // current board when the user comes back to this window.
      this.pullSnapshotFromOpener();
    },
    pullSnapshotFromOpener() {
      const host = this.openerHost();
      const snapshot = host?.getValidationBlockersSnapshot?.();
      this.snapshot = snapshot || null;
      // CORE-6454: the symptom chips need the opener's AI-table flag
      this.hasAiTable = !!host?.has_ai_table;
      this.orphaned = !this.hasOpener();
    },
    /** The opener pushes a fresh board when the document or its errors change. */
    setBlockers(snapshot: ValidationBlockers | null, docId?: string) {
      // The opener switched documents — follow it so the window always shows
      // the blockers of the document the user is actually on.
      if (docId && docId !== this.docId) {
        this.$router.replace({
          path: '/show_validation_assistant/' + encodeURIComponent(docId),
        });
      }
      this.snapshot = snapshot || null;
      // A push is proof the opener is alive.
      if (snapshot) this.orphaned = false;
    },
    applySavedSize() {
      const saved = readSavedSize();
      const width = saved?.width ?? DEFAULT_WIDTH;
      const height = saved?.height ?? DEFAULT_HEIGHT;
      try {
        // The popup may have been opened with the default features already; a
        // stored preference still lets the window re-fit itself on open.
        if (window.outerWidth && window.outerHeight) {
          if (window.outerWidth !== width || window.outerHeight !== height) {
            window.resizeTo(width, height);
          }
        }
        // Center it on the screen.
        const left = Math.max(0, Math.round((screen.width - width) / 2));
        const top = Math.max(0, Math.round((screen.height - height) / 2));
        if (window.screenX !== undefined) {
          window.moveTo(left, top);
        }
      } catch {
        // resizeTo/moveTo are not allowed for all window kinds — best effort.
      }
    },
    persistSize() {
      try {
        if (window.outerWidth && window.outerHeight) {
          localStorage.setItem(
            SIZE_KEY,
            JSON.stringify({ width: window.outerWidth, height: window.outerHeight }),
          );
        }
      } catch {
        // ignore storage errors
      }
    },
    closeWindow() {
      this.persistSize();
      this.handOverChat();
      window.close();
    },
    panelRef(): PanelConversationApi | null {
      return (this.$refs.panel as PanelConversationApi | undefined) || null;
    },
    // CORE-6161: the popout continues the docked chat instead of starting empty.
    pullConversationFromOpener() {
      const state = this.openerHost()?.getValidationAssistantConversation?.();
      if (state) this.panelRef()?.importConversation?.(state);
    },
    syncConversationToOpener(state: unknown) {
      this.openerHost()?.syncValidationAssistantConversation?.(state);
    },
    handOverChat() {
      const host = this.openerHost();
      if (!host) return;
      const state = this.panelRef()?.exportConversation?.();
      if (state) host.restoreValidationAssistantConversation?.(state);
      host.onValidationAssistantWindowClosed?.();
    },
    notifyParentOnClose() {
      // CORE-6161: closing the popup hands the chat back and leaves compact
      // mode; the browser's own close button goes through beforeunload, so the
      // in-app close and the X both end here.
      this.handOverChat();
    },
  },
});
</script>

<style lang="scss" scoped>
.validation-assistant-window {
  height: 100vh;
  overflow: hidden;
  background: var(--card);
}
</style>